css:
.wrapper {
  position: relative;
}

.btn-delete {
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  user-select: none;
  border: none;
  border-radius: 10px;
  padding: 0.5rem 1.4rem 0.5rem 1rem;
  background-color: rgb(255, 0, 0);
  background-image: radial-gradient(circle at 50% -50%, #fff, 10%, #0000);

  font-family: "Inter", sans-serif;
  font-weight: 600;
  font-size: 0.9em;
  color: #fff;
  cursor: pointer;

  box-shadow:
    0px 1px 1px rgba(3, 7, 18, 0.16),
    0px 3px 4px rgba(3, 7, 18, 0.14),
    0px 7px 9px rgba(3, 7, 18, 0.11),
    0px 12px 16px rgba(3, 7, 18, 0.09),
    0px 19px 26px rgba(3, 7, 18, 0.07),
    0px 27px 37px rgba(3, 7, 18, 0.05),
    0px 37px 50px rgba(3, 7, 18, 0.02);
  transition:
    box-shadow 0.3s ease,
    transform 0.15s ease;
}

.btn-delete::after,
.btn-delete::before {
  content: "";
  position: absolute;
  top: calc(50% - 10px);
  left: 0px;
  width: 10px;
  aspect-ratio: 1 / 2;
  border-radius: 35%;
  background-color: inherit;
  opacity: 1;
  transition:
    left 0.3s ease,
    right 0.3s ease,
    opacity 0.3s ease;
}
.btn-delete::after {
  left: auto;
  right: 0px;
}

.btn-svg {
  width: 24px;
  height: 24px;
  fill: #fff9;
  stroke: #fff0;
  transition: transform 0.3s ease;
}

.btn-delete:hover {
  box-shadow:
    0px 3px 4px rgba(3, 7, 18, 0.13),
    0px 14px 17px rgba(3, 7, 18, 0.11),
    0px 31px 38px rgba(3, 7, 18, 0.09),
    0px 55px 67px rgba(3, 7, 18, 0.07),
    0px 86px 105px rgba(3, 7, 18, 0.06),
    0px 124px 151px rgba(3, 7, 18, 0.04),
    0px 169px 206px rgba(3, 7, 18, 0.02);

  transform: scale(1.07);
}

.btn-delete:hover .btn-svg {
  transform: rotate(-8deg) scale(1.8);
}

.btn-delete:hover::after {
  opacity: 1;
  right: -4px;
}
.btn-delete:hover::before {
  opacity: 1;
  left: -4px;
}

.btn-delete:active::after {
  right: 0px;
}
.btn-delete:active::before {
  left: 0px;
}

.document {
  z-index: -1;
  position: absolute;
  top: -180%;
  left: 50%;
  width: 78%;
  height: 160px;
  background-color: #fff;
  border: 1px solid #0002;
  transform: translate(-50%, 0%) scale(0);
  transition:
    transform 0.3s ease,
    opacity 1s ease;
  filter: drop-shadow(0 0 5px #0001);
  opacity: 0;
}

.btn-delete:hover ~ .document {
  transform: translate(-50%, -30%) scale(1);
  opacity: 1;
}

.btn-delete:focus ~ .document {
  animation: feed 1.5s forwards;
  transform: translate(-50%, -50%) scale(1);
}

.shredded {
  position: absolute;
  z-index: -1;
  stroke: #fff;
  fill: none;
  stroke-width: 0;
  filter: drop-shadow(0 0 5px #0001);
}

.btn-delete:focus ~ .shredded {
  animation: shred 1.5s cubic-bezier(1, 0.6, 0.6, 1) reverse;
}

@keyframes feed {
  0% {
    clip-path: inset(0% 0% 0% 0%);
  }
  100% {
    clip-path: inset(100% 0% 0% 0%);
  }
}

@keyframes shred {
  0% {
    stroke-width: 9;
    opacity: 0;
    clip-path: inset(0% 0% 0% 0%);
  }
  30% {
    opacity: 1;
  }
  100% {
    stroke-width: 9;
    clip-path: inset(0% 0% 100% 0%);
  }
}
